/* See hwscreen.h. Everything here has to work on the worst boot there is: no
 * serial, no disk, no fonts, no desktop. So the font is compiled in
 * (hwscreen_font.h, generated by tools/mkbitmapfont.py), pixels go through
 * fb_fill_rect/fb_present only, and waits use the monotonic clock, not the
 * scheduler: this runs on the boot thread in place of wm_run(). */
#include <stddef.h>
#include <stdint.h>
#include "hwscreen.h"
#include "hwscreen_font.h"

#ifndef HWSCREEN_HOST_TEST
#include "fb.h"
#include "klog.h"
#include "ktime.h"
#include "kprintf.h"
#include "serial.h"
#include "bootmark.h"
#include "pit.h"
#endif

int hwscreen_wrap(const char *text, int cols, char (*out)[161], int max_lines)
{
    if (cols > 160) cols = 160;
    if (cols < 1) return 0;
    int n = 0, col = 0;
    for (const char *p = text; *p && n < max_lines; p++) {
        if (*p == '\n') { out[n][col] = 0; n++; col = 0; continue; }
#ifndef HWSCREEN_NEGCTL_NO_WRAP
        if (col == cols) { out[n][col] = 0; if (++n >= max_lines) break; col = 0; }
#else
        if (col == cols) col = cols - 1;
#endif
        char c = *p;
        out[n][col++] = (c >= 0x20 && c < 0x7f) ? c : (c == '\t' ? ' ' : '?');
    }
    if (n < max_lines && col) { out[n][col] = 0; n++; }
    return n;
}

#ifndef HWSCREEN_HOST_TEST

#define MAX_LINES 2400
static char g_text[256 * 1024];
static char g_lines[MAX_LINES][161];
static int  g_order[MAX_LINES * 2];       /* summary indices, then every line */

static const char *const summary_prefix[] = {
    "[hw]", "[board]", "[efi]", "[ahci]", "[blk]", "[fs]", "[cpu]", "[mce]", "[smp]", "LOGIT_",
};

/* klog_format_rec() lines read "[    0.340] I cpu0 [hw] ...". Keep the time,
 * drop the padding, level and CPU so a line carries more of its message. */
static int compact(char *line, int len)
{
    if (len < 4 || line[0] != '[') return len;
    int i = 1, o = 0;
    while (i < len && line[i] == ' ') i++;
    while (i < len && line[i] != ']') line[o++] = line[i++];
    if (i >= len) return len;
    i++;                                                 /* past "]" */
    while (i < len && line[i] == ' ') i++;
    if (i + 1 < len && line[i + 1] == ' ') i += 2;          /* level letter */
    if (i + 3 < len && line[i] == 'c' && line[i + 1] == 'p' && line[i + 2] == 'u') {
        while (i < len && line[i] != ' ') i++;
        while (i < len && line[i] == ' ') i++;
    }
    line[o++] = ' ';
    while (i < len) line[o++] = line[i++];
    return o;
}

static int is_summary(const char *s)
{
    while (*s && *s != ' ') s++;                   /* the compacted time */
    while (*s == ' ') s++;
    for (size_t i = 0; i < sizeof summary_prefix / sizeof summary_prefix[0]; i++) {
        const char *a = summary_prefix[i], *b = s;
        while (*a && *a == *b) a++, b++;
        if (!*a) return 1;
    }
    return 0;
}

static int collect(void)
{
    struct klog_rec r;
    size_t len = 0;
    for (uint64_t seq = klog_first_seq(); seq < klog_next_seq() && len + 300 < sizeof g_text; seq++) {
        if (!klog_get(seq, &r)) continue;
        int n = klog_format_rec(&r, g_text + len, (int)(sizeof g_text - len - 1));
        if (n > 0) len += (size_t)compact(g_text + len, n);
        if (len && g_text[len - 1] != '\n') g_text[len++] = '\n';
    }
    g_text[len] = 0;
    return len ? 1 : 0;
}

static void glyph(int x, int y, char c, int s, uint32_t fg)
{
    if (c < 0x20 || c > 0x7e) c = '?';
    const uint8_t *g = hwscreen_font[c - 0x20];
    for (int row = 0; row < HWSCREEN_FONT_H; row++)
        for (int col = 0; col < HWSCREEN_FONT_W; col++)
            if (g[row] & (0x80 >> col)) fb_fill_rect(x + col * s, y + row * s, s, s, fg);
}

static void line(int x, int y, const char *s, int s_, uint32_t fg)
{
    for (; *s; s++, x += HWSCREEN_FONT_W * s_) glyph(x, y, *s, s_, fg);
}

static void wait_ms(unsigned ms)
{
    uint64_t end = time_mono_ns() + (uint64_t)ms * 1000000ull;
    /* pause, not hlt: on a machine whose timer interrupt does not arrive a
     * halt never wakes, and the report would never turn its first page */
    while (time_mono_ns() < end) __asm__ volatile ("sti; pause");
}

static void utoa(unsigned v, char *b)
{
    char t[12]; int n = 0;
    do t[n++] = (char)('0' + v % 10); while (v /= 10);
    while (n) *b++ = t[--n];
    *b = 0;
}

void hwscreen_report(void)
{
    int W = (int)fb_width(), H = (int)fb_height();
    int s = W >= 1600 ? 2 : 1;                           /* 16x32 cells at 1080p */
    int cols = W / (HWSCREEN_FONT_W * s); if (cols > 160) cols = 160;
    int rows = H / (HWSCREEN_FONT_H * s) - 2;            /* two header rows */
    uint32_t bg = fb_rgb(8, 10, 16), fg = fb_rgb(220, 226, 236), hi = fb_rgb(120, 200, 255),
             dim = fb_rgb(120, 130, 150);
    bootcon_stop();                                      /* the report owns the screen now */
    kprintf("[hwscreen] no root filesystem: showing the boot log on screen (%dx%d cells)\n", cols, rows);
    for (;;) {
        collect();
        int n = hwscreen_wrap(g_text, cols, g_lines, MAX_LINES), m = 0;
        int cap = (int)(sizeof g_order / sizeof g_order[0]);
        for (int i = 0; i < n && m < cap / 2; i++) if (is_summary(g_lines[i])) g_order[m++] = i;
        int nsum = m;
        for (int i = 0; i < n && m < cap; i++) g_order[m++] = i;
        int pages = rows > 0 ? (m + rows - 1) / rows : 0;
        for (int p = 0; p < pages; p++) {
            fb_fill_rect(0, 0, W, H, bg);
            char hdr[200] = "LogitOS boot report - no root filesystem - photograph each page - page ";
            char num[12];
            size_t k = 0; while (hdr[k]) k++;
            utoa((unsigned)p + 1, num); for (char *q = num; *q; q++) hdr[k++] = *q;
            hdr[k++] = '/'; utoa((unsigned)pages, num); for (char *q = num; *q; q++) hdr[k++] = *q;
            const char *part = p * rows < nsum ? "  [summary]" : "  [full log]";
            for (const char *q = "  pit ticks "; *q; q++) hdr[k++] = *q;
            utoa((unsigned)timer_ticks(), num); for (char *q = num; *q; q++) hdr[k++] = *q;
            for (const char *q = part; *q; q++) hdr[k++] = *q;
            hdr[k] = 0;
            line(0, 0, hdr, s, hi);
            for (int r = 0; r < rows && p * rows + r < m; r++) {
                int idx = g_order[p * rows + r];
                line(0, (r + 2) * HWSCREEN_FONT_H * s, g_lines[idx], s, p * rows + r < nsum ? fg : dim);
            }
            fb_present();
            /* serial only: logging each page would fill the very ring being
             * shown and push the boot evidence out of it */
            char msg[48] = "[hwscreen] page ", nb[12];
            size_t q = 16;
            utoa((unsigned)p + 1, nb); for (char *c = nb; *c; c++) msg[q++] = *c;
            msg[q++] = '/'; utoa((unsigned)pages, nb); for (char *c = nb; *c; c++) msg[q++] = *c;
            msg[q++] = '\n'; msg[q] = 0;
            serial_puts(msg);
            wait_ms(HWSCREEN_PAGE_MS);
        }
    }
}
#endif
